// Original genshin-db v5.2.14 data (MIT); generated missing-record indexes.
// Browser-safe compressed ArrayBuffer: no Node.js Buffer dependency.
(() => {
  const encoded = "";
  const bytes = Uint8Array.from(atob(encoded), char => char.charCodeAt(0));
  window.GenshinDb.addData(bytes.buffer, false);
})();
